def maps():
    out={}
    for K,P in ((P1K,P1),(P2K,P2),(P3K,P3)):
        for row in P.split('|'):
            s,*v=row.split()
            for k,x in zip(K,v):
                if x!='-': out.setdefault(k,{})[s]=float(x)
    for k,S in (("is he cheating",CHEAT),("situationship",SITU)):
        t=S.split(); out[k]={t[i]:float(t[i+1]) for i in range(0,len(t),2)}
    return out
